  const defaultSla = {'Crítica':1,'Alta':4,'Média':24,'Baixa':72};
  const escapeHtml = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmtDate = (value, opts={}) => new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',...opts}).format(new Date(value)).replace(' de ',' ');
  const fmtDateTime = value => new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value)).replace(' de ',' ');
