  function loadState(){try{const parsed=JSON.parse(localStorage.getItem(STORE_KEY));if(parsed&&Array.isArray(parsed.incidents)){const maxId=parsed.incidents.reduce((max,item)=>Math.max(max,Number(String(item?.id||'').split('-').pop())||0),0);parsed.nextId=Math.max(Number(parsed.nextId)||1043,maxId+1);parsed.incidents=parsed.incidents.map(item=>({...item,client:item.client||'',channel:item.channel||'',region:item.region||'',technicianId:item.technicianId||'',history:Array.isArray(item.history)?item.history:[]}));return {...parsed,schemaVersion:2,assets:Array.isArray(parsed.assets)?parsed.assets:[],techs:Array.isArray(parsed.techs)?parsed.techs:baseTechs,sla:{...defaultSla,...parsed.sla},waitEscalation:{lowToMediumHours:24,mediumToHighHours:8,...parsed.waitEscalation}}}}catch(e){}return {schemaVersion:2,incidents:seedIncidents.map(item=>({...item,client:''})),assets:[],techs:baseTechs,sla:defaultSla,waitEscalation:{lowToMediumHours:24,mediumToHighHours:8},nextId:1043,seeded:true}}
